/**
 * Export the OpenAPI document generated from the Nest app to a JSON file.
 *
 * Document 17 §1: "OpenAPI documentation is generated from backend
 * definitions and must remain synchronized with implementation".
 * Document 40: the canonical response envelope + error code groups
 * are reflected in the exported document.
 *
 * The script writes to `apps/api/dist/openapi/openapi.json`. The
 * canonical committed artifact lives at
 * `docs/openapi/openapi.json` and is regenerated by the P3-002 /
 * P3-010 pipeline.
 *
 * `DATABASE_URL` is required for NestFactory.create because
 * AppModule imports DatabaseModule which instantiates PrismaService.
 * For local-only OpenAPI export a minimal stub URL is acceptable;
 * the application never connects because no HTTP listener binds.
 */
import 'dotenv/config';
import 'reflect-metadata';

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { NestFactory } from '@nestjs/core';
import { FastifyAdapter, type NestFastifyApplication } from '@nestjs/platform-fastify';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';

import { AppModule } from '../src/app.module.js';

if (!process.env['DATABASE_URL']) {
  process.env['DATABASE_URL'] = 'postgresql://stub:stub@127.0.0.1:5432/stub';
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const outDir = join(__dirname, '..', 'dist', 'openapi');
mkdirSync(outDir, { recursive: true });

async function main(): Promise<void> {
  const app = await NestFactory.create<NestFastifyApplication>(
    AppModule,
    new FastifyAdapter({ logger: false }),
    {
      logger: false,
    },
  );
  const config = new DocumentBuilder()
    .setTitle('FASTFOOD API')
    .setDescription(
      'FASTFOOD canonical OpenAPI document. Generated from the Nest app definition. The response envelope follows document 40 (success / list / error) and the canonical error code groups from packages/contracts/error-codes.',
    )
    .setVersion('0.0.0-phase3')
    .addBearerAuth()
    .addApiKey({ type: 'apiKey', name: 'Idempotency-Key', in: 'header' }, 'Idempotency-Key')
    .build();
  const document = SwaggerModule.createDocument(app, config);
  const out = join(outDir, 'openapi.json');
  writeFileSync(out, JSON.stringify(document, null, 2));
  process.stderr.write(`Wrote ${out}\n`);
  await app.close();
}

main().catch((error) => {
  process.stderr.write(`openapi:export failed: ${(error as Error).stack ?? error}\n`);
  process.exit(1);
});
